import{c as o,Q as l,j as a,m as e}from"./chunks/framework.DOi4mjdC.js";const p="data:image/png;base64,",g="/assets/%E7%A4%BA%E6%84%8F%E5%9B%BE.D8S0tS69.png",s="/assets/%E8%BD%B4%E7%A4%BA%E6%84%8F%E5%9B%BE.D6zrwD8k.png",B=JSON.parse('{"title":"算子基本概念","description":"","frontmatter":{},"headers":[{"level":1,"title":"算子基本概念","slug":"算子基本概念"},{"level":2,"title":"算子名称（Op Name）","slug":"算子名称op-name"},{"level":2,"title":"算子类型（Op Type）","slug":"算子类型op-type"},{"level":2,"title":"张量（Tensor）","slug":"张量tensor"},{"level":2,"title":"形状（Shape）","slug":"形状shape"},{"level":2,"title":"轴（axis）","slug":"轴axis"}],"relativePath":"guide/技术附录/概念原理和术语/神经网络和算子/算子基本概念.md","filePath":"guide/技术附录/概念原理和术语/神经网络和算子/算子基本概念.md"}'),n={name:"guide/技术附录/概念原理和术语/神经网络和算子/算子基本概念.md"};function r(u,t,i,d,q,c){return l(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="算子基本概念" tabindex="-1">算子基本概念 <a class="header-anchor" href="#算子基本概念" aria-label="Permalink to &quot;算子基本概念&quot;">​</a></h1><p>算子（Operator，简称OP），是深度学习算法中执行特定数学运算或操作的基础单元，例如激活函数（如ReLU）、卷积（Conv）、池化（Pooling）以及归一化（如Softmax）。通过组合这些算子，可以构建神经网络模型。</p><p>本章节介绍算子中常用的基本概念。</p><h2 id="算子名称-op-name" tabindex="-1">算子名称（Op Name） <a class="header-anchor" href="#算子名称-op-name" aria-label="Permalink to &quot;算子名称（Op Name）&quot;">​</a></h2><p>算子的名称，用于标识网络中的某个算子，同一网络中算子的名称需要保持唯一。如下图所示Conv1、Pool1、Conv2都是此网络中的算子名称，其中Conv1与Conv2算子的类型为Convolution，表示分别做一次卷积运算。</p><p><strong>图 1</strong> 网络拓扑示例<br><img src="'+p+'" alt="" title="网络拓扑示例"></p><h2 id="算子类型-op-type" tabindex="-1">算子类型（Op Type） <a class="header-anchor" href="#算子类型-op-type" aria-label="Permalink to &quot;算子类型（Op Type）&quot;">​</a></h2><p>网络中每一个算子根据算子类型进行算子实现的匹配，相同类型算子的实现逻辑相同。在一个网络中同一类型的算子可能存在多个，例如上图中的Conv1算子与Conv2算子的类型都为Convolution。</p><h2 id="张量-tensor" tabindex="-1">张量（Tensor） <a class="header-anchor" href="#张量-tensor" aria-label="Permalink to &quot;张量（Tensor）&quot;">​</a></h2><p>Tensor是算子计算数据的容器，包含如下属性信息。</p><p><strong>表 1</strong> Tensor属性信息</p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;28.199999999999996%&quot;&gt;&lt;p&gt;属性&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;71.8%&quot;&gt;&lt;p&gt;定义&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;28.199999999999996%&quot;&gt;&lt;p&gt;形状&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;71.8%&quot;&gt;&lt;p&gt;Tensor的形状，比如(10, )或者(1024, 1024)或者(2, 3, 4)等。如形状(3, 4)表示第一维有3个元素，第二维有4个元素，(3, 4)表示一个3行4列的矩阵数组。&lt;/p&gt; &lt;p&gt;形式：(i1, i2, …, in)，其中i1到in均为正整数。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;28.199999999999996%&quot;&gt;&lt;p&gt;数据类型&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;71.8%&quot;&gt;&lt;p&gt;指定Tensor对象的数据类型。&lt;/p&gt; &lt;p&gt;取值范围：float16, float32, int8, int16, int32, uint8, uint16, bfloat16, bool等。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;28.199999999999996%&quot;&gt;&lt;p&gt;数据排布格式&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;71.8%&quot;&gt;&lt;p&gt;数据的物理排布格式，详细请参见&lt;a href=&quot;数据排布格式.md&quot;&gt;数据排布格式。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p><h2 id="形状-shape" tabindex="-1">形状（Shape） <a class="header-anchor" href="#形状-shape" aria-label="Permalink to &quot;形状（Shape）&quot;">​</a></h2><p>张量的形状，以(D0, D1, … ,Dn-1)的形式表示，D0到Dn是任意的正整数。</p><p>如形状(3,4)表示第一维有3个元素，第二维有4个元素，(3,4)表示一个3行4列的矩阵数组。</p><p>形状的第一个元素对应张量最外层中括号中的元素个数，形状的第二个元素对应张量中从左边开始数第二个中括号中的元素个数，依此类推。例如：</p><p><strong>表 2</strong> 张量的形状举例</p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;27.339999999999996%&quot;&gt;&lt;p&gt;张量&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;34.4%&quot;&gt;&lt;p&gt;形状&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;38.26%&quot;&gt;&lt;p&gt;描述&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;27.339999999999996%&quot;&gt;&lt;p&gt;1&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;34.4%&quot;&gt;&lt;p&gt;(0,)&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;38.26%&quot;&gt;&lt;p&gt;0维张量，也是一个标量&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;27.339999999999996%&quot;&gt;&lt;p&gt;[1,2,3]&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;34.4%&quot;&gt;&lt;p&gt;(3,)&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;38.26%&quot;&gt;&lt;p&gt;1维张量&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;27.339999999999996%&quot;&gt;&lt;p&gt;[[1,2],[3,4]]&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;34.4%&quot;&gt;&lt;p&gt;(2, 2)&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;38.26%&quot;&gt;&lt;p&gt;2维张量&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;27.339999999999996%&quot;&gt;&lt;p&gt;[[[1,2],[3,4]], [[5,6],[7,8]]]&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;34.4%&quot;&gt;&lt;p&gt;(2, 2, 2)&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;38.26%&quot;&gt;&lt;p&gt;3维张量&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p><p>物理含义我们应该怎么理解呢？假设我们有这样一个shape=(4, 20, 20, 3)。</p><p>假设有一些照片，每个像素点都由红/绿/蓝3色组成，即shape里面3的含义，照片的宽和高都是20，也就是20*20=400个像素，总共有4张的照片，这就是shape=(4, 20, 20, 3)的物理含义。</p><p><strong>图 2</strong> 示意图<br><img src="'+g+`" alt="" title="示意图"></p><p>如果体现在编程上，可以简单把shape理解为操作Tensor的各层循环，比如我们要对shape=(4, 20, 20, 3)的A tensor进行操作，循环语句如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>produce A {</span></span>
<span class="line"><span>  for (i, 0, 4) {</span></span>
<span class="line"><span>    for (j, 0, 20) {</span></span>
<span class="line"><span>      for (p, 0, 20) {</span></span>
<span class="line"><span>        for (q, 0, 3) {</span></span>
<span class="line"><span>          A[((((((i*20) + j)*20) + p)*3) + q)] = a_tensor[((((((i*20) + j)*20) + p)*3) + q)]</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>      }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div><h2 id="轴-axis" tabindex="-1">轴（axis） <a class="header-anchor" href="#轴-axis" aria-label="Permalink to &quot;轴（axis）&quot;">​</a></h2><p>轴是相对shape来说的，轴代表张量的shape的下标，比如张量a是一个5行6列的二维数组，即shape是(5,6)，则axis=0表示是张量中的第一维，即行。axis=1表示是张量中的第二维，即列。</p><p>例如张量数据[[[1,2],[3,4]], [[5,6],[7,8]]]，Shape为(2,2,2)，则轴0代表第一个维度的数据即[[1,2],[3,4]]与[[5,6],[7,8]]这两个矩阵，轴1代表第二个维度的数据即[1,2]、[3,4]、[5,6]、[7,8]这四个数组，轴2代表第三个维度的数据即1，2，3，4，5，6，7，8这八个数。</p><p>轴axis可以为负数，此时表示是倒数第axis个维度。</p><p>N维Tensor的轴有：0 , 1, 2,……，N-1。</p><p><strong>图 3</strong> 轴示意图<br><img src="`+s+'" alt="" title="轴示意图"></p>',29)])])}const b=o(n,[["render",r]]);export{B as __pageData,b as default};
